const body = $('Content webhook').first().json.body;
const today = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const isDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s + 'T00:00:00Z')) && new Date(s + 'T00:00:00Z').toISOString().slice(0, 10) === s;
const dayKo = s => '일월화수목금토'[new Date(s + 'T00:00:00Z').getUTCDay()];
const addDays = (s, n) => new Date(Date.parse(s + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
// LLM이 날짜를 지어내지 않았는지: 요청 문장에 날짜를 말하는 표현이 있어야 날짜를 믿는다
const mentionsDate = text => /\d{1,2}\s*월|\d{1,2}\s*일|\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\/\d{1,2}|오늘|내일|모레|글피|요일|이번\s*주|다음\s*주|주말|월말|월초/.test(String(text ?? ''));
const range = (a, b) => (!b || a === b) ? `${a}(${dayKo(a)})` : `${a}(${dayKo(a)}) ~ ${b}(${dayKo(b)})`;
function parseJson(output) {
  const raw = String(output ?? '');
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start < 0 || end < start) throw new Error('no JSON');
  return JSON.parse(raw.slice(start, end + 1));
}
const user = String(body.user).trim();
const product = body.product && typeof body.product.name === 'string' && body.product.name.trim() ? body.product : null;
const sourceText = typeof body.text === 'string' ? body.text.trim() : '';
const AGENT = { copy: 'a3-copy', sns: 'a3-sns', schedule: 'a3-content-schedule', other: '담당자 연결' };
let parsed;
try { parsed = parseJson($json.output); if (!Array.isArray(parsed.tasks)) throw new Error('no tasks'); }
catch (error) { return [{ json: { count: 0, results: [], error: 'split_failed' } }]; }
// LLM이 할 일을 하나도 못 찾으면 낱말 규칙으로 한 번 더 찾는다 (예: "게시 일정 잡아 줘")
if (!parsed.tasks.some(t => t && typeof t.text === 'string' && t.text.trim())) {
  const m = String(body.message);
  parsed.tasks = [
    [/소개글|소개 글|카피|상세 설명/, 'copy'], [/sns|인스타|트위터|엑스|\bx\b|링크드인|줄여/i, 'sns'], [/일정|게시|올릴|업로드/, 'schedule'],
  ].filter(([re]) => re.test(m)).map(([re, type]) => ({ type, text: m.trim() }));
}
const seen = new Set();
const tasks = parsed.tasks.filter(t => t && typeof t.text === 'string' && t.text.trim())
  .map(t => ({ type: AGENT[t.type] ? t.type : 'other', text: t.text.trim() }))
  .filter(t => t.type === 'other' || (!seen.has(t.type) && seen.add(t.type)));
const ALIAS = { instagram: 'instagram', x: 'x', linkedin: 'linkedin' };
const bodyChannels = Array.isArray(body.channels) ? body.channels : [];
const channels = [...new Set([...(parsed.channels || []), ...bodyChannels].map(c => ALIAS[String(c).toLowerCase()] || String(c)))];
const date = mentionsDate(body.message) && isDate(parsed.date) ? parsed.date : (isDate(body.date) ? body.date : '');
const has = type => tasks.some(t => t.type === type);
const results = tasks.map((t, i) => ({ index: i + 1, type: t.type, text: t.text, agent: AGENT[t.type], route: '', answer: '', detail: {} }));
const mark = (type, route, answer) => results.filter(r => r.type === type).forEach(r => { r.route = route; r.answer = answer; });
const run = { copy: false, sns: false, schedule: false };
if (has('copy')) {
  if (product) run.copy = true;
  else mark('copy', '입력 필요', '소개글을 쓰려면 제품 정보를 함께 보내 주세요. 예: "product": {"name": "루미 무선 이어폰", "price": 89000, "features": ["노이즈 캔슬링"]}');
}
if (has('sns')) {
  if (run.copy || sourceText) run.sns = true;  // 소개글이 먼저 나오거나, 원문(text)이 있어야 한다
  else mark('sns', '입력 필요', has('copy') ? '소개글을 먼저 만들어야 SNS 글을 만들 수 있어요. 제품 정보를 보내 주세요.' : '줄일 원문 글(text)을 보내 주거나, 소개글 쓰기를 함께 요청해 주세요.');
}
if (has('schedule')) {
  if (!date) mark('schedule', '입력 필요', '게시 날짜를 알려 주세요. 예: "11월 2일에 올릴게"');
  else if (date < today) mark('schedule', '거절', `${date}은 이미 지난 날짜예요. 오늘(${today}) 이후 날짜로 알려 주세요.`);
  else run.schedule = true;
}
mark('other', '담당자 연결', '콘텐츠 제작 창구에서는 소개글 · SNS 글 · 게시 일정만 도와드려요. 이 요청은 마케팅 담당자에게 전달했습니다.');
return [{ json: { count: results.length, user, product, source_text: sourceText, channels, date, tone: String(parsed.tone ?? '').trim(), run, results, copy_text: '' } }];

const state = JSON.parse(JSON.stringify($('Need copy?').first().json));
const entry = state.results.find(r => r.type === 'copy');
if ($json.route && $json.text) {
  Object.assign(entry, { route: $json.route, answer: $json.text, detail: { source: $json.source, length: $json.length } });
  state.copy_text = $json.text;
} else {
  Object.assign(entry, { route: '담당자 연결', answer: '소개글 Agent가 응답하지 않아 마케팅 담당자에게 전달했습니다.' });
  if (state.run.sns && !state.source_text) {
    state.run.sns = false;
    state.results.filter(r => r.type === 'sns').forEach(r => Object.assign(r, { route: '입력 필요', answer: '소개글을 만들지 못해 SNS 글도 만들지 않았어요. 잠시 뒤 다시 요청해 주세요.' }));
  }
}
return [{ json: state }];

const state = JSON.parse(JSON.stringify($('Need SNS?').first().json));
const entry = state.results.find(r => r.type === 'sns');
if ($json.route && Array.isArray($json.posts)) Object.assign(entry, { route: $json.route, answer: $json.answer, detail: { posts: $json.posts } });
else Object.assign(entry, { route: '담당자 연결', answer: 'SNS 글 Agent가 응답하지 않아 마케팅 담당자에게 전달했습니다.' });
return [{ json: state }];

const state = JSON.parse(JSON.stringify($('Need schedule?').first().json));
const entry = state.results.find(r => r.type === 'schedule');
if ($json.route && $json.answer) Object.assign(entry, { route: $json.route, answer: $json.answer, detail: { event: $json.event ?? null, conflicts: $json.conflicts ?? [] } });
else Object.assign(entry, { route: '담당자 연결', answer: '일정 Agent가 응답하지 않아 마케팅 담당자에게 전달했습니다.' });
return [{ json: state }];

const results = [...($json.results ?? [])].sort((a, b) => a.index - b.index);
const user = String($('Content webhook').first().json.body.user ?? '').trim();
const ICON = { '자동 답변': '✅', '접수 완료': '📝', '등록 완료': '📅', '거절': '⛔', '입력 필요': '❓', '담당자 연결': '🙋' };
const oneLine = value => String(value ?? '').replace(/\s+/g, ' ').trim();
// 여러 줄 답(SNS 채널별 글)은 줄을 살려 들여 쓴다
const block = value => String(value ?? '').split('\n').map(oneLine).filter(Boolean).join('\n   ');
const lines = results.map(r => `${r.index}. ${ICON[r.route] ?? '•'} [${r.route}] ${block(r.answer)}`);
const ask = results.filter(r => r.route === '입력 필요').map(r => r.index);
const handed = results.filter(r => r.route === '담당자 연결').map(r => r.index);
const tail = [];
if (ask.length) tail.push(`❓ ${ask.join(', ')}번은 필요한 정보를 알려 주시면 바로 처리할게요.`);
if (handed.length) tail.push(`🙋 ${handed.join(', ')}번은 담당자가 이어서 연락드립니다.`);
const reply = [`${user} 님, 요청하신 ${results.length}가지를 정리했어요.`, ...lines, ...tail].join('\n');
return [{ json: { count: results.length, results, reply } }];
